const FS={global:{query:'',field:'',page:0,size:10,sort:'openrank',selected:['1','2','3']},lf:{query:'',field:'',page:0,size:10,sort:'openrank',selected:FR.children.slice(0,3).map(r=>r.id)},historyScope:'global',start:'2025-07',end:'2026-06',history:{global:Object.keys(D.foundationMonth.rows[0]).slice(1,4),lf:FR.children.slice(0,5).map(r=>r.id)}};
