function frFiltered(scope){const st=FS[scope],q=st.query.trim().toLocaleLowerCase();return frRows(scope).filter(r=>(!st.field||r.field===st.field)&&[r.label,r.name,r.foundation,r.short,r.field,...(r.projects||[]).map(p=>p.name)].some(v=>String(v||'').toLocaleLowerCase().includes(q))).sort((a,b)=>N(b[st.sort])-N(a[st.sort])||N(a.rank)-N(b.rank));}
