function frSource(b,opener){const scope=frScope(b);openOverlay(b,`<div class="cr-source-grid"><section><h4>${scope==='lf'?'真实身份，模拟排名':'原始底表与代表项目'}</h4><p>${scope==='lf'?'旗下组织与项目名称来自官方名录；OpenRank、开发者数和月度位次暂为模拟。官方名录没有提供这些排名值。':'全球榜的 21 家主体、原榜次和指标均沿用固定版本底表；月度表覆盖其中八家。'}</p><p>Linux 基金会整体与旗下组织分榜比较。原表还单列 OpenInfra 等主体，组织范围可能重叠；不将各条目分值或开发者数相加。</p><p>代表项目按 ${E(FR.retrieved_at)} 可见的官方资料核对，不代表完整项目清单，也不替代报告期内的历史项目映射。历史实体仍保留原表名称。</p><p>名次变化是位置变化，不是分值增长率。缺失值不补零；组织成立前的模拟月份不绘制。</p></section><section><h4>下载与核对</h4>${['foundation','foundationMonth'].map(k=>`<div class="cr-source-file"><a href="${base}/assets/gosr/data/${D[k].file}" download>${E(D[k].title)} · 原始 CSV ↓</a><br><a href="${source}data/processed/chapter3/${D[k].file}" target="_blank" rel="noopener">固定版本来源 ↗</a></div>`).join('')}<p><a href="https://landscape.linuxfoundation.org/" target="_blank" rel="noopener">Linux 基金会官方 Landscape ↗</a><br><a href="${base}/assets/gosr/foundation-reference.json" download>组织 / 代表项目来源清单 ↓</a><br><a href="${base}/assets/gosr/foundation-lf-simulated.json" download>旗下组织模拟指标与轨迹 ↓</a></p></section></div>`,'source',opener);}
