function renderFoundation(b,keep=false){if(b.g===3)return frHistoryRender(b);S['3'].views[b.g-1]==='compare'?frComparison(b):frRanking(b,keep);}
function frGo(b,group){closeOverlay(b,false);const target=B.find(x=>x.s==='3'&&x.g===group);if(b.dialog?.open){b.dialog.querySelector('.slide-presentation-bar > button')?.click();target.launch?.click();}else document.getElementById(`fig-3-3-${group}`)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
function frAdd(b,id){const st=FS[frScope(b)];if(st.selected.includes(id)||!frFind(frScope(b),id))return;if(st.selected.length>=3){b.status.textContent='最多对照 3 家，请先移除一家。';return false;}st.selected.push(id);return true;}
function frAction(b,action,node){const scope=frScope(b),st=FS[scope];switch(action){
 case 'source':frSource(b,node);return true;
 case 'image':frExportImage(b);return true;
 case 'export':frDownload(b);return true;
 case 'close':closeOverlay(b);return true;
 case 'back':frGo(b,1);return true;
 case 'reset':Object.assign(st,{query:'',field:'',page:0,sort:'openrank'});break;
 case 'compare':S['3'].views[b.g-1]='compare';break;
 case 'ranking':S['3'].views[b.g-1]='ranking';break;
 case 'clear-selection':st.selected=[];break;
 case 'default-selection':st.selected=frRows(scope).slice(0,3).map(r=>r.id);break;
 case 'profile':frProfile(b,scope,node.dataset.frId,node);return true;
 case 'children':frGo(b,2);return true;
 case 'track':FS.historyScope=node.dataset.frScope;FS.history[FS.historyScope]=[node.dataset.frId];S['3'].views[2]='monthly';render(B.find(x=>x.s==='3'&&x.g===3));frGo(b,3);return true;
 case 'history-all':FS.history[scope]=frHistoryKeys(scope).slice(0,10);break;
 case 'history-clear':FS.history[scope]=[];break;
 case 'six-months':FS.start='2026-01';FS.end='2026-06';break;
 case 'full-year':FS.start='2025-07';FS.end='2026-06';break;
 default:return false;
 }render(b);return true;}
function frClick(b,node){const scope=frScope(b),st=FS[scope];if(node.dataset.frAction)return frAction(b,node.dataset.frAction,node);if(node.dataset.frProfile){frProfile(b,node.dataset.frScope||scope,node.dataset.frProfile,node);return true;}if(node.dataset.frHistoryScope){FS.historyScope=node.dataset.frHistoryScope;render(b);return true;}if(node.dataset.frPage!==undefined){st.page=N(node.dataset.frPage);render(b);return true;}if(node.dataset.frSort){st.sort=node.dataset.frSort;st.page=0;render(b);return true;}if(node.dataset.frRemove){st.selected=st.selected.filter(id=>id!==node.dataset.frRemove);render(b);return true;}return false;}
function frChange(b,el){const scope=frScope(b),st=FS[scope];if(el.dataset.frCheck){if(el.checked){if(frAdd(b,el.dataset.frCheck)===false){el.checked=false;return true;}}else st.selected=st.selected.filter(id=>id!==el.dataset.frCheck);render(b);return true;}if(el.dataset.frHistory){const ns=FS.history[scope];if(el.checked){if(ns.length>=10){el.checked=false;b.status.textContent='最多比较 10 家，请先取消一家。';return true;}if(!ns.includes(el.dataset.frHistory))ns.push(el.dataset.frHistory);}else FS.history[scope]=ns.filter(n=>n!==el.dataset.frHistory);render(b);return true;}if(el.dataset.frSetting){const key=el.dataset.frSetting;if(key==='add'){if(frAdd(b,el.value)===false){el.value='';return true;}}else if(['start','end'].includes(key)){FS[key]=el.value;if(FS.end<FS.start)FS.end=FS.start;}else{st[key]=key==='size'?N(el.value):el.value;st.page=0;}render(b);return true;}return false;}
