const prStatus=r=>r.data_status==='simulated'?'模拟补位':'原表记录';
function prRows(scope=S['4'].scope){return [...D[scope].rows,...(scope==='project'?PX.extension:[])].map(r=>{const m=PR.projects[r.project]||{};return {...r,domain:m.domain||'未分类',subdomain:m.subdomain||'待补',object_type:m.object_type||'待核验',website:m.website||'',country_label:clean(r.country_zh)||(scope==='chinaProject'?'中国':'未识别'),country_basis:scope==='chinaProject'?'中国榜样本标签；非历史发起地证明':r.country_zh?'原表国家标签；非历史发起地证明':'未核验',organization_label:r.initiator_zh||'未识别',data_status:r.data_status||'report_source',rank_status:r.rank_status||'原榜次',value_status:r.value_status||'报告底表原值',classification_status:'editorial_reference'};});}
