function prSummary(b,rows,noteText){setData(b,rows,noteText,rows.some(r=>r.data_status==='simulated'||r.data_status==='mixed_simulated'));}
function prTools(b,keep=false){const st=S['4'];b.el.querySelector('.cr-head h4').textContent=st.scope==='project'?'全球项目影响力 Top 100':'中国项目影响力 Top 30';b.el.querySelector('.cr-head-right>span').textContent=st.scope==='project'?'30 条原表 · 70 条模拟补位':'2025.07—2026.06 · 原表';if(!keep)b.toolbar.innerHTML=scopes('4')+select('size','每页',[10,20,50,100],st.size)+`<label class="cr-search">检索<input type="search" data-rr-search value="${E(st.query)}" placeholder="项目 / 领域 / 组织 / 国家" aria-label="检索完整项目榜单"></label>`+btn('重置','reset');}
