function prRanking(b,keep=false){const st=S['4'],all=prFiltered(),full=prRows(),max=Math.max(...full.map(r=>N(r.openrank))),maxDev=Math.max(...full.map(r=>N(r.active_developers))),structure=st.views[0]==='structure';prTools(b,keep);st.page=Math.min(st.page,Math.max(0,Math.ceil(all.length/st.size)-1));const rs=all.slice(st.page*st.size,(st.page+1)*st.size);const sort=(key,t)=>`<button data-rr-sort="${key}" aria-pressed="${st.sort===key}">${t} ${st.sort===key?'↓':'↕'}</button>`;
 b.body.innerHTML=`<div class="pr-ranking">${prFilters()}<div class="cr-rank-caption"><span>${st.scope==='project'?'Top 100 评审名单 · 31—100 位为模拟':'中国榜 · 原表 30 项'} / ${st.sort==='openrank'?'按影响力浏览':'按活跃开发者浏览，保留榜次'}</span><span>领域为编辑分类 · 零基线 / 整榜尺度</span></div><div class="rr-rank-scroll" role="table" aria-label="项目影响力榜单"><div class="cr-rank-header pr-grid" role="row"><span role="columnheader">榜次</span><span role="columnheader">项目 / 组织标签</span><span role="columnheader">领域 / 细分方向</span><span role="columnheader">${sort('openrank','OpenRank')}</span><span role="columnheader">${sort('active_developers','活跃开发者')}</span><span role="columnheader">国家 · 原表归属</span><span role="columnheader">对照</span></div><div class="rr-rank-list" role="rowgroup">${rs.map(r=>`<div class="cr-rank-row pr-grid" role="row" data-top="${N(r.rank)<=3}" data-evidence="${r.data_status}"><span class="cr-rank-no" role="cell">${String(r.rank).padStart(2,'0')}</span><div role="cell">${prName(r)}</div><div class="pr-domain" role="cell"><span>${E(r.domain)}</span><small>${E(r.subdomain)}</small></div><div role="cell">${bar(r.openrank,max,2)}</div><div role="cell" class="pr-dev">${structure?bar(r.active_developers,maxDev,0,'var(--gv-cyan)'):F(r.active_developers)}</div><div class="pr-country-cell" role="cell">${E(r.country_label)}${r.country_label==='未识别'?'<small>未核验</small>':''}</div><label class="cr-check" role="cell"><input type="checkbox" data-pr-check="${E(uid(st.scope,r))}" ${selected('4').includes(uid(st.scope,r))?'checked':''} aria-label="将 ${E(r.project)} 加入对照"></label></div>`).join('')||empty()}</div></div>${pages(b,all.length)}</div>`;
 prSummary(b,all,`${st.scope==='project'?'全球评审名单':'中国原榜'} · ${all.length} 项匹配 · CSV 导出全部匹配项，SVG 导出当前页 · 原表归属不等于贡献来源`);
}
function prComparison(b){const st=S['4'],scope=st.scope,full=prRows(),rs=selected('4').map(id=>prRecord(id)).filter(Boolean);prTools(b);b.body.innerHTML=`<div class="cr-compare"><div class="cr-compare-tools">${select('add','添加项目',[['','选择同榜项目…'],...full.filter(r=>!selected('4').includes(uid(scope,r))).map(r=>[uid(scope,r),`${r.rank}. ${r.project}${r.data_status==='simulated'?'（模拟）':''}`])],'')}<span>同一榜单 · 最多 3 项</span>${btn('恢复默认','default-selection')}</div>${rs.length?`<div class="rr-table-wrap"><table class="cr-comparison-table"><thead><tr><th>${scopeNames[scope]}<br>2025.07—2026.06</th>${rs.map(r=>`<th><button class="cr-remove" data-rr-remove="${E(uid(scope,r))}" data-rr-dataset="${scope}" aria-label="移除 ${E(r.project)}">×</button><small>第 ${r.rank} 位 · ${prStatus(r)}</small><h4>${E(r.project)}</h4></th>`).join('')}</tr></thead><tbody>${[['OpenRank',r=>bar(r.openrank,Math.max(...full.map(x=>N(x.openrank))),2)],['活跃开发者',r=>F(r.active_developers)],['领域',r=>E(r.domain)+'<br>'+E(r.subdomain)],['国家标签',r=>E(r.country_label)],['原表组织标签',r=>E(r.organization_label)],['统计对象',r=>E(r.object_type)],['身份与边界',r=>prName(r)]].map(([label,fn])=>`<tr><th>${label}</th>${rs.map(r=>`<td class="rr-text-cell">${fn(r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('尚未选择项目。')}${note('模拟补位只用于界面评审；统计对象的仓库边界待核验，不能跨对象简单相加。')}</div>`;prSummary(b,rs,`${scopeNames[scope]}同榜对照 · ${rs.length} 项 · 领域为编辑分类`);}
function prProfile(b,id,scope,opener){const r=prRecord(id,scope);if(!r)return;const m=PR.projects[r.project];openOverlay(b,`<span class="cr-eyebrow">${scopeNames[scope]} · ${prStatus(r)}</span><h4>${E(r.project)}</h4><p>${E(r.domain)} / ${E(r.subdomain)}</p><div class="cr-profile-rank"><b>${r.rank}</b><span>${r.data_status==='simulated'?'模拟补位，不是正式全球名次':'本期原榜次'}</span></div><div class="cr-profile-metrics"><div><small>OpenRank${r.data_status==='simulated'?' · 模拟':''}</small><strong>${F(r.openrank,2)}</strong></div><div><small>活跃开发者${r.data_status==='simulated'?' · 模拟':''}</small><strong>${F(r.active_developers)}</strong></div></div>${table(['属性','当前记录'],[['国家归属',E(r.country_label)+' · '+E(r.country_basis)],['原表组织标签',E(r.organization_label)],['历史发起国家 / 发起者','待核验；原表可能记录托管方'],['统计对象',E(r.object_type)],['仓库清单 / 归并边界','待补，未用官网仓库列表替代原始映射']],'pr-profile-table')}<p>${E(m?.note||'映射证据待补。')}</p>${m?.website?`<p><a href="${E(m.website)}" target="_blank" rel="noopener">项目官方入口 ↗</a> · 用于名称与技术领域参考</p>`:''}<p>领域为编辑分类，非官方分类。${r.data_status==='simulated'?PX.extension_note:''}</p>${PX.contribution_records.some(x=>x.project===r.project)?`<button data-pr-contribution="${E(r.project)}">查看贡献来源 · 模拟评审 ↗</button>`:''}`,'profile',opener);flagLabels(b.overlay);}
function prCountryRows(){const rs=D.projectCountries.rows.map(r=>({...r,country_zh:clean(r.country_zh),data_status:'report_source'})).sort((a,b)=>a.country_zh==='未识别'?1:b.country_zh==='未识别'?-1:N(b.projects_in_top100)-N(a.projects_in_top100));let last=null,rank=0;return rs.map((r,i)=>{if(r.country_zh!=='未识别'&&N(r.projects_in_top100)!==last)rank=i+1;last=N(r.projects_in_top100);return {...r,count_rank:r.country_zh==='未识别'?'':rank,share_pct:N(r.projects_in_top100),denominator:100};});}
function prAux(b){const st=S['4'],v=st.views[1];b.el.querySelector('.cr-head-right>span').textContent='各视图保留独立样本与口径';b.toolbar.innerHTML=(v==='country'?'<span class="cr-period">原表 Top 100 汇总 · 分母 100 · 未识别置底</span>':v==='domain'?select('auxScope','分类样本',[['project','全球原表 Top 30'],['review','全球评审 Top 100（含模拟）'],['chinaProject','中国原表 Top 30']],st.auxScope):'<span class="rr-pending">中国项目 · 基期待确认 · 原始两期记录</span>')+btn('返回项目主榜','back');
 if(v==='country'){const rs=prCountryRows();b.body.innerHTML=`<div class="pr-aux">${table(['数量排名','国家 / 地区','入榜项目','样本占比','原表代表项目'],rs.map(r=>[r.count_rank?`<span class="rr-country-rank">${rs.filter(x=>x.count_rank===r.count_rank).length>1?'并列 ':''}${r.count_rank}</span>`:'—',E(r.country_zh),bar(r.projects_in_top100,69,0,r.country_zh==='未识别'?'var(--gv-muted)':'var(--gv-brand)'),F(r.share_pct)+'%',E(r.representative_projects)]),'pr-country-table')}${note('12 个已识别国家共 91 项；未识别 9 项保留在分母并放在最后。此图直接使用原表汇总，不由评审补位名单回算。')}</div>`;prSummary(b,rs,'全球 Top 100 原表国家汇总 · 数量相同并列跳位 · 未识别不参与排名');return;}
 if(v==='domain'){const review=st.auxScope==='review',scope=st.auxScope==='chinaProject'?'chinaProject':'project',full=prRows(scope).filter(r=>review||r.data_status==='report_source'),counts=PR.domains.map(domain=>{const rows=full.filter(r=>r.domain===domain);return {domain,count:rows.length,share_pct:rows.length/full.length*100,representative_projects:rows.slice(0,3).map(r=>`${r.project}（${r.data_status==='simulated'?'模拟位次 ':''}${r.rank}）`).join('、'),source_count:rows.filter(r=>r.data_status==='report_source').length,simulated_count:rows.filter(r=>r.data_status==='simulated').length,denominator:full.length,data_status:review?'mixed_simulated':'report_source',classification_status:'editorial_reference'};}).filter(r=>r.count).sort((a,b)=>b.count-a.count);b.body.innerHTML=`<div class="pr-aux"><div class="pr-aux-caption">${review?'<b class="pr-sim-label">含模拟补位 · 仅描述当前评审名单</b>':'原表名单 × 编辑领域分类'}<span>每项一个主领域 · 分母 ${full.length}</span></div>${table(['领域','项目数量','样本占比','代表项目 / 当前榜次'],counts.map(r=>[E(r.domain),bar(r.count,Math.max(...counts.map(x=>x.count)),0),F(r.share_pct,1)+'%',E(r.representative_projects)]),'pr-domain-table')}${note('每个项目按主要用途归入一个领域；跨领域属性保留在细分方向中。该图不表示各领域的整体市场规模。')}</div>`;prSummary(b,counts,`${review?'评审名单含 70 条模拟补位':scopeNames[scope]+'原表'} · 分母 ${full.length} · 9 类编辑分类，官网证据见项目档案`);return;}
 const rs=D.rising.rows.map(r=>({...r,domain:PR.projects[r.project]?.domain||'待补',organization_label:prRows('chinaProject').find(x=>x.project===r.project)?.organization_label||'未识别',baseline_status:'基期待确认',data_status:'report_source'}));b.body.innerHTML=`<div class="pr-aux">${table(['项目 / 领域','原表组织标签','基期 → 本期','位次变化','本期 OpenRank'],rs.map(r=>[`<strong>${E(r.project)}</strong><small class="pr-sub">${E(r.domain)}</small>`,E(r.organization_label),`<span class="pr-rank-move">${E(r.prev_rank)} <span>→</span> <b>${E(r.cur_rank)}</b></span>`,`<span class="rr-change">${E(r.rank_delta)}</span>`,F(r.openrank,2)]),'pr-rising-table')}${note('“新进”不折算为数值位移。两期的基期日期尚未提供，不计算增长率。各表保留原始精度：CANN 跃升表 14,719.50，主榜 14,719.47。')}</div>`;prSummary(b,rs,'中国项目两期记录 · 基期日期未提供 · 不生成月度轨迹或增长率');}
const PRCOLORS=['#ba613c','#276c8a','#5d8f83','#9b7b39','#726b9e','#b9798a','#6f93a4','#bdc5ca'];
function prContributionRows(project,repo='all'){return PX.contribution_records.filter(r=>r.project===project&&(repo==='all'||r.repository_group===repo));}
function prMarginal(rows,key,labels){const total=rows.reduce((a,r)=>a+r.merged_prs,0);return labels.map((label,i)=>{const id=typeof label==='string'?label:label.id,name=typeof label==='string'?label:label.name,count=rows.filter(r=>r[key]===id).reduce((a,r)=>a+r.merged_prs,0);return {id,name,count,share:total?count/total*100:0,color:PRCOLORS[i%8]};});}
function prCountries(rows){return prMarginal(rows,'country',PX.countries);}
function prStack(rows){return `<div class="pr-stack" role="img" aria-label="${E(rows.map(r=>`${r.name} ${F(r.share,1)}%`).join('；'))}">${rows.map(r=>`<span style="width:${r.share}%;background:${r.color}" title="${E(r.name)} · ${F(r.share,1)}%">${r.share>=12?F(r.share,0)+'%':''}</span>`).join('')}</div>`;}
function prLead(rows){const cs=prCountries(rows),ranked=cs.filter(x=>!['其他已识别','未识别'].includes(x.id)).sort((a,b)=>b.count-a.count),leader=ranked[0],runner=ranked[1],unknown=cs.find(x=>x.id==='未识别'),other=cs.find(x=>x.id==='其他已识别');return {leader,runner,coverage:100-unknown.share,gap:leader.share-runner.share,stable:leader.share>Math.max(runner.share,other.share)+unknown.share};}
function prBars(rs){const ordered=[...rs].sort((a,b)=>['未识别','unknown'].includes(a.id)?1:['未识别','unknown'].includes(b.id)?-1:b.count-a.count);return `<div class="pr-detail-bars">${ordered.map(r=>`<div class="pr-detail-bar"><span>${E(r.name)}</span><strong>${F(r.share,1)}%</strong><span class="pr-detail-track"><i style="width:${r.share}%;background:${r.color}"></i></span><small>${F(r.count)} PR</small></div>`).join('')}</div>`;}
