 if(view==='detail'){b.body.innerHTML=`<div class="pr-detail"><div class="pr-detail-summary"><div><small>模拟第一贡献来源</small><strong>${E(lead.leader.name)} <em>${F(lead.leader.share,1)}%</em></strong><span>领先第二来源 ${F(lead.gap,1)} 个百分点</span></div><div><small>模拟首要组织力量</small><strong>${E(org.name)} <em>${F(org.share,1)}%</em></strong><span>匿名角色；不对应真实企业</span></div><div><small>国家识别覆盖 / 合并 PR</small><strong>${F(lead.coverage,1)}% <em>/ ${F(total)}</em></strong><span>未识别 ${F(100-lead.coverage,1)}% 保留在分母</span></div></div><div class="pr-detail-columns"><section><h5>贡献国家 / 地区</h5>${prBars(cs)}</section><section><h5>组织与独立贡献者</h5>${prBars(os)}</section></div><p class="pr-insight">${lead.stable?'模拟中，'+E(lead.leader.name)+'是较明确的第一贡献来源'+(lead.leader.share>50?'，占全部贡献的一半以上':'，但未超过全部贡献的一半')+'。':'模拟中，未识别份额可能改变第一来源判断。'} 此处描述贡献集中程度；治理决策权仍需维护者与章程证据。</p></div>`;prSummary(b,[...cs.map(c=>({project,repository_group:repo,dimension:'country',category:c.name,merged_prs:c.count,share_pct:c.share,denominator:total,data_status:'simulated'})),...os.map(c=>({project,repository_group:repo,dimension:'organization',category:c.name,merged_prs:c.count,share_pct:c.share,denominator:total,data_status:'simulated'}))],`${project} · ${repo==='all'?'全部仓库组':PX.repository_groups.find(x=>x.id===repo).name} · 国家与组织是同一份 ${F(total)} PR 的两种分布`);return;}
 b.body.innerHTML=`<div class="pr-aux"><div class="pr-aux-caption"><b>${E(project)} · 模拟贡献记录</b><span>${rs.length} 个非零单元格 · ${F(total)} 条 PR</span></div>${table(['仓库组（模拟）','贡献者所在地','组织力量（模拟）','合并 PR'],rs.map(r=>[E(PX.repository_groups.find(x=>x.id===r.repository_group).name),E(r.country),E(PX.organizations.find(x=>x.id===r.organization).name),F(r.merged_prs)]),'pr-record-table')}${note('每个单元格对应“仓库组 × 国家 × 组织”。同一 PR 仅计一次；跨图可核对总量。真实仓库映射与组织归属证据后续补齐。')}</div>`;prSummary(b,rs.map(r=>({...r,repository_label:PX.repository_groups.find(x=>x.id===r.repository_group).name,organization_label:PX.organizations.find(x=>x.id===r.organization).name})),`${project} · 联合贡献表 · 合并 PR 数 · 全部贡献数量与分组模拟`);
